const dishTypeIcon = (type: DishType) => { const Icon = type === 'DRINK' ? Coffee : type === 'DESSERT' ? CakeSlice : type === 'STARTER' ? Salad : Utensils; return <Icon className="size-4" aria-hidden="true" />; };
