function draftFromItem(item: RestaurantMenuItem, categoryId = item.categoryId): Draft {
  const metadata = item.metadata || {}; const availability = metadata.availability || {}; const inventory = metadata.inventoryConfig || {};
  const gallery = arrayFrom(metadata.gallery); const images = gallery.length ? gallery : item.imageUrl ? [item.imageUrl] : [];
  return { ...emptyDraft, categoryId, productId: item.productId || '', variantId: String(inventory.variantId || ''), name: item.name, nameEn: metadata.nameEn || '', description: item.description || '', descriptionEn: metadata.descriptionEn || '', dishType: metadata.dishType || 'DRINK', prepMinutes: String(metadata.prepMinutes || 5), price: String(item.price ?? ''), taxRate: String(item.taxRate ?? 0), prepStation: item.prepStation || 'KITCHEN', imageUrl: images[0] || '', gallery: images, tags: arrayFrom(metadata.tags), allergens: arrayFrom(metadata.allergens), dietary: arrayFrom(metadata.dietary), inventoryMode: metadata.inventoryMode || (item.productId ? 'FINISHED_PRODUCT' : 'NONE'), deductWhen: inventory.deductWhen || 'SENT_TO_KITCHEN', shortageBehavior: inventory.shortageBehavior || 'WARN', allowSubstitutions: Boolean(inventory.allowSubstitutions), state: availability.state || (item.isAvailable ? 'AVAILABLE' : 'HIDDEN'), channels: { ...emptyDraft.channels, ...(availability.channels || {}) }, temporaryPause: Boolean(availability.temporaryPause), featured: Boolean(availability.featured || item.isFeatured), options: item.options || [], recipeLines: (inventory.recipeLines || []).map((line, index) => ({ id: line.id || `ingredient-${index}`, productId: String(line.productId || ''), variantId: String(line.variantId || ''), name: line.name, quantity: Number(line.quantity || 0), unit: line.unit || 'unidad', unitCost: Number(line.unitCost || 0), wastePercent: Number(line.wastePercent || 0) })), schedule: emptySchedule().map((row) => availability.schedule?.find((entry) => entry.day === row.day) || row) };
}
function metadataFromDraft(draft: Draft): RestaurantMenuMetadata {
  const deductWhen = draft.deductWhen === 'ORDER_CONFIRMED' ? 'ORDER_CREATED' : draft.deductWhen === 'ITEM_PREPARED' ? 'DELIVERED' : draft.deductWhen;
  return { nameEn: draft.nameEn.trim() || undefined, descriptionEn: draft.descriptionEn.trim() || undefined, dishType: draft.dishType, prepMinutes: Number(draft.prepMinutes) || 0, tags: draft.tags, allergens: draft.allergens, dietary: draft.dietary, gallery: draft.gallery, inventoryMode: draft.inventoryMode, inventoryConfig: { deductWhen, shortageBehavior: draft.shortageBehavior, allowSubstitutions: draft.allowSubstitutions, variantId: draft.variantId || undefined, recipeLines: draft.recipeLines }, availability: { state: draft.state, channels: draft.channels, temporaryPause: draft.temporaryPause, featured: draft.featured, schedule: draft.schedule } };
}
function TagInput({ label, values, onChange, placeholder }: { label: string; values: string[]; onChange: (values: string[]) => void; placeholder: string }) {
  const [value, setValue] = useState(''); const add = () => { const next = value.trim(); if (next && !values.includes(next)) onChange([...values, next]); setValue(''); };
  return <label className="block text-sm font-bold"><span>{label}</span><div className="mt-2 flex min-h-11 flex-wrap gap-2 rounded-xl border border-input bg-background p-2">{values.map((item, index) => <Badge key={item} variant="secondary" className={`nh-menu-tag-chip gap-1 rounded-lg ${index % 3 === 0 ? 'nh-menu-tag-chip-green' : index % 3 === 1 ? 'nh-menu-tag-chip-blue' : 'nh-menu-tag-chip-pink'}`}>{item}<button type="button" onClick={() => onChange(values.filter((current) => current !== item))} aria-label={`Quitar ${item}`}><X className="size-3" /></button></Badge>)}<input value={value} onChange={(event) => setValue(event.target.value)} onKeyDown={(event) => { if (event.key === 'Enter') { event.preventDefault(); add(); } }} onBlur={add} placeholder={placeholder} className="min-w-32 flex-1 bg-transparent px-1 py-1 text-xs outline-none" /></div></label>;
}
function DishGallery({ draft, imageInputRef, galleryInputRef, canEdit, saving, uploadItemImage, uploadGalleryImage, removeGalleryImage }: { draft: Draft; imageInputRef: RefObject<HTMLInputElement | null>; galleryInputRef: RefObject<HTMLInputElement | null>; canEdit: boolean; saving: boolean; uploadItemImage: (file?: File) => Promise<void>; uploadGalleryImage: (file?: File) => Promise<void>; removeGalleryImage: (image: string) => Promise<void> }) {
  return <div className="nh-menu-gallery-section"><div className="flex flex-wrap items-start justify-between gap-3"><div><p className="font-serif text-xl font-medium italic text-primary">Fotos del platillo</p><p className="mt-1 text-sm text-muted-foreground">La primera imagen será la principal en tu menú público.</p></div><span className="rounded-full bg-accent/10 px-3 py-1 text-xs font-semibold text-primary">{draft.gallery.length || (draft.imageUrl ? 1 : 0)} imágenes</span></div><div className="nh-menu-gallery-grid mt-4"><div className="nh-menu-gallery-main relative overflow-hidden rounded-2xl border border-accent/30 bg-muted"><input ref={imageInputRef} type="file" accept="image/*" className="hidden" onChange={(event) => { void uploadItemImage(event.target.files?.[0]); event.currentTarget.value = ''; }} />{draft.imageUrl ? <img src={draft.imageUrl} alt="Imagen principal del platillo" className="size-full object-cover" /> : <div className="flex size-full min-h-48 items-center justify-center text-muted-foreground"><Utensils className="size-10" /></div>}<span className="absolute left-3 top-3 rounded-full bg-accent px-3 py-1 text-xs font-black text-accent-foreground">Principal</span><button type="button" onClick={() => imageInputRef.current?.click()} disabled={!canEdit || saving} className="absolute inset-x-3 bottom-3 flex items-center justify-center gap-2 rounded-xl bg-black/65 px-3 py-2 text-xs font-black text-white transition hover:bg-black/80"><ImagePlus className="size-4" />{draft.imageUrl ? 'Cambiar imagen' : 'Agregar imagen'}</button></div><div className="nh-menu-gallery-thumbs">{draft.gallery.slice(1, 4).map((image, index) => <div key={image} className="relative overflow-hidden rounded-xl border border-border/60 bg-muted"><img src={image} alt={'Imagen ' + (index + 2) + ' del platillo'} className="size-full object-cover" /><button type="button" onClick={() => void removeGalleryImage(image)} disabled={!canEdit || saving} aria-label="Eliminar imagen" className="absolute right-2 top-2 flex size-7 items-center justify-center rounded-lg bg-white/90 text-destructive shadow-sm transition hover:bg-white"><Trash2 className="size-3.5" /></button></div>)}<input ref={galleryInputRef} type="file" accept="image/*" className="hidden" onChange={(event) => { void uploadGalleryImage(event.target.files?.[0]); event.currentTarget.value = ''; }} /><button type="button" onClick={() => galleryInputRef.current?.click()} disabled={!canEdit || saving} className="flex min-h-24 items-center justify-center gap-2 rounded-xl border border-dashed border-accent/40 bg-accent/5 px-3 text-xs font-black text-primary transition hover:bg-accent/10"><Plus className="size-4" />Agregar foto</button></div></div></div>;
}
function PreviewCard({ draft }: { draft: Draft }) {
  return <aside className="rounded-2xl border border-accent/25 bg-accent/5 p-4"><div className="flex items-center gap-2"><Eye className="size-5 text-primary" /><div><p className="font-serif text-xl font-medium italic text-primary">Vista previa</p><p className="text-xs text-muted-foreground">Así se verá en el menú público.</p></div></div><div className="mt-4 overflow-hidden rounded-2xl border border-border/60 bg-card shadow-sm"><div className="aspect-[1.55] bg-muted">{draft.imageUrl ? <img src={draft.imageUrl} alt="Vista previa del platillo" className="size-full object-cover" /> : <div className="flex size-full items-center justify-center text-muted-foreground"><Utensils className="size-8" /></div>}</div><div className="p-4"><div className="flex items-start justify-between gap-2"><div><p className="font-black">{draft.name || 'Nombre del platillo'}</p><p className="mt-1 text-xs leading-5 text-muted-foreground">{draft.description || 'Descripción breve y atractiva para tus clientes.'}</p></div><span className="shrink-0 font-black text-accent">{draft.price ? money(draft.price) : 'C$ 0.00'}</span></div></div></div><div className="mt-4 rounded-2xl border border-accent/20 bg-accent/10 p-4"><p className="font-black text-primary">Consejos para una mejor presentación</p>{['Usa imágenes nítidas y bien iluminadas.', 'Escribe una descripción breve y atractiva.', 'Selecciona la categoría correcta.', 'Mantén el precio actualizado.'].map((tip) => <p key={tip} className="mt-2 text-xs text-muted-foreground">✓ {tip}</p>)}</div></aside>;
}

function InventoryBindingFields({ draft, onChange }: { draft: Draft; onChange: (patch: Partial<Pick<Draft, 'productId' | 'variantId'>>) => void }) {
  const [products, setProducts] = useState<any[]>([]);
  useEffect(() => { const controller = new AbortController(); inventoryService.getAllProductLookupPages({ pageSize: 200, type: 'PRODUCT', includeInactive: false }, controller.signal).then((response) => setProducts(Array.isArray(response?.data) ? response.data : [])).catch(() => undefined); return () => controller.abort(); }, []);
  const selected = products.find((product) => String(product.id) === String(draft.productId));
  const variants = Array.isArray(selected?.variants) ? selected.variants : [];
  return <div className="grid gap-4 rounded-2xl border border-accent/20 bg-accent/5 p-4 md:grid-cols-2"><label className="text-sm font-bold"><span>Producto de inventario</span><select className="mt-2 h-10 w-full rounded-xl border border-input bg-background px-3 text-sm" value={draft.productId} onChange={(event) => onChange({ productId: event.target.value, variantId: '' })}><option value="">Sin vínculo · venta sin inventario</option>{products.map((product) => <option key={product.id} value={product.id}>{product.code ? `${product.code} · ` : ''}{product.name}</option>)}</select><small className="mt-1 block text-xs font-normal text-muted-foreground">Vincúlalo para descontar existencias al confirmar, preparar o cobrar.</small></label>{variants.length > 0 && <label className="text-sm font-bold"><span>Variante</span><select className="mt-2 h-10 w-full rounded-xl border border-input bg-background px-3 text-sm" value={draft.variantId} onChange={(event) => onChange({ variantId: event.target.value })}><option value="">Primera variante disponible</option>{variants.map((variant: any) => <option key={variant.id} value={variant.id}>{variant.sku || variant.name || variant.id}</option>)}</select></label>}</div>;
}

function RecipeBindingFields({ draft, onChange }: { draft: Draft; onChange: (patch: Partial<Draft>) => void }) {
  const [products, setProducts] = useState<any[]>([]);
  useEffect(() => { const controller = new AbortController(); inventoryService.getAllProductLookupPages({ pageSize: 200, type: 'PRODUCT', includeInactive: false }, controller.signal).then((response) => setProducts(Array.isArray(response?.data) ? response.data : [])).catch(() => undefined); return () => controller.abort(); }, []);
  if (!['RECIPE', 'COMPONENTS', 'ASSEMBLED'].includes(draft.inventoryMode) || !draft.recipeLines.length) return null;
  return <div className="rounded-2xl border border-accent/20 bg-accent/5 p-4"><p className="font-black text-primary">Vínculo de insumos</p><p className="mt-1 text-xs text-muted-foreground">Cada línea debe apuntar a un producto activo para descontar existencias.</p><div className="mt-3 space-y-2">{draft.recipeLines.map((line) => <label key={line.id} className="grid gap-2 text-sm font-bold sm:grid-cols-[minmax(0,1fr)_minmax(0,1fr)]"><span className="flex items-center rounded-xl border border-border/60 bg-background px-3 py-2">{line.name || 'Insumo sin nombre'}</span><select className="h-10 rounded-xl border border-input bg-background px-3 text-sm" value={line.productId || ''} onChange={(event) => onChange({ recipeLines: draft.recipeLines.map((current) => current.id === line.id ? { ...current, productId: event.target.value } : current) })}><option value="">Seleccionar producto de inventario</option>{products.map((product) => <option key={product.id} value={product.id}>{product.code ? `${product.code} · ` : ''}{product.name}</option>)}</select></label>)}</div></div>;
}

export function RestaurantMenuWorkspace({ menu, onSaved, canCreate, canEdit, canConfigureRestaurant, canExport, publicLink }: { menu: RestaurantMenuCategory[]; onSaved: () => Promise<void>; canCreate: boolean; canEdit: boolean; canConfigureRestaurant: boolean; canExport: boolean; publicLink?: string }) {
  const [view, setView] = useState<MenuView>('catalog'); const [editorTab, setEditorTab] = useState<EditorTab>('general'); const [selectedCategoryId, setSelectedCategoryId] = useState('ALL'); const [search, setSearch] = useState(''); const [statusFilter, setStatusFilter] = useState('ALL'); const [typeFilter, setTypeFilter] = useState('ALL'); const [tagFilter, setTagFilter] = useState('ALL'); const [sortFilter, setSortFilter] = useState('recent'); const [editingItemId, setEditingItemId] = useState<string | null>(null); const [draft, setDraft] = useState<Draft>(emptyDraft); const [categoryForm, setCategoryForm] = useState({ id: '', name: '', description: '' }); const [categoryModalOpen, setCategoryModalOpen] = useState(false); const [saving, setSaving] = useState(false); const [importing, setImporting] = useState(false); const [theme, setTheme] = useState<'modern' | 'classic' | 'elegant' | 'rustic' | 'neon' | 'tropical' | 'editorial' | 'retro'>('modern'); const [showImages, setShowImages] = useState(true); const [showDescriptions, setShowDescriptions] = useState(true); const [showPrices, setShowPrices] = useState(true); const [showAllergens, setShowAllergens] = useState(false); const [showFooter, setShowFooter] = useState(true); const [language, setLanguage] = useState<'ES' | 'EN' | 'BOTH'>('ES'); const [templateFilter, setTemplateFilter] = useState('Todas las plantillas'); const [languageFilter, setLanguageFilter] = useState('Todas'); const [optimizedFilter, setOptimizedFilter] = useState('Todos'); const [designStep, setDesignStep] = useState<'appearance' | 'content' | 'publication'>('appearance'); const [logoPreview, setLogoPreview] = useState(''); const [coverPreview, setCoverPreview] = useState(''); const [primaryColor, setPrimaryColor] = useState('#01422C'); const [accentColor, setAccentColor] = useState('#74C044'); const [showQr, setShowQr] = useState(false); const [qrPreview, setQrPreview] = useState(''); const fileInputRef = useRef<HTMLInputElement | null>(null); const imageInputRef = useRef<HTMLInputElement | null>(null); const galleryInputRef = useRef<HTMLInputElement | null>(null); const logoInputRef = useRef<HTMLInputElement | null>(null); const coverInputRef = useRef<HTMLInputElement | null>(null);
  useEffect(() => { const controller = new AbortController(); restaurantService.getMenuSettings(controller.signal).then((settings) => { if (settings?.theme) setTheme(settings.theme); if (typeof settings?.showImages === 'boolean') setShowImages(settings.showImages); if (typeof settings?.showDescriptions === 'boolean') setShowDescriptions(settings.showDescriptions); if (typeof settings?.showPrices === 'boolean') setShowPrices(settings.showPrices); if (typeof settings?.showAllergens === 'boolean') setShowAllergens(settings.showAllergens); if (typeof settings?.showFooter === 'boolean') setShowFooter(settings.showFooter); if (settings?.language) setLanguage(settings.language); }).catch(() => undefined); restaurantService.getConfiguration(controller.signal).then((response) => { const profile = response?.profile; if (profile?.logo) setLogoPreview(profile.logo); if (profile?.coverImage) setCoverPreview(profile.coverImage); if (profile?.primaryColor) setPrimaryColor(profile.primaryColor); if (profile?.accentColor) setAccentColor(profile.accentColor); }).catch(() => undefined); return () => controller.abort(); }, []);
  const allItems = useMemo(() => menu.flatMap((category) => category.items.map((item) => ({ item, category }))), [menu]); const allTags = useMemo(() => Array.from(new Set(allItems.flatMap(({ item }) => arrayFrom(item.metadata?.tags)))), [allItems]); const previewImages = useMemo(() => allItems.map(({ item }) => item.imageUrl).filter((image): image is string => Boolean(image)).slice(0, 3), [allItems]);
  const visibleItems = useMemo(() => { const filtered = allItems.filter(({ item, category }) => { const query = `${item.name} ${item.description || ''} ${arrayFrom(item.metadata?.tags).join(' ')}`.toLowerCase(); const state = item.metadata?.availability?.state || (item.isAvailable ? 'AVAILABLE' : 'HIDDEN'); const type = item.metadata?.dishType || 'DRINK'; return (selectedCategoryId === 'ALL' || category.id === selectedCategoryId) && query.includes(search.toLowerCase().trim()) && (statusFilter === 'ALL' || state === statusFilter) && (typeFilter === 'ALL' || type === typeFilter) && (tagFilter === 'ALL' || arrayFrom(item.metadata?.tags).includes(tagFilter)); }); if (sortFilter === 'name') return filtered.sort((a, b) => a.item.name.localeCompare(b.item.name)); if (sortFilter === 'price') return filtered.sort((a, b) => Number(a.item.price) - Number(b.item.price)); return filtered; }, [allItems, search, selectedCategoryId, statusFilter, typeFilter, tagFilter, sortFilter]);
  const selectedCategory = selectedCategoryId === 'ALL' ? undefined : menu.find((category) => category.id === selectedCategoryId); const updateDraft = <K extends keyof Draft>(key: K, value: Draft[K]) => setDraft((current) => ({ ...current, [key]: value }));
  const openEditor = (item?: RestaurantMenuItem, categoryId?: string) => { setEditingItemId(item?.id || null); setDraft(item ? draftFromItem(item, categoryId) : { ...emptyDraft, categoryId: categoryId || menu[0]?.id || '' }); setEditorTab('general'); setView('editor'); };
  const openCategoryEditor = (category?: RestaurantMenuCategory) => { setCategoryForm(category ? { id: category.id, name: category.name, description: category.description || '' } : { id: '', name: '', description: '' }); setCategoryModalOpen(true); }; const resetCategory = () => { setCategoryForm({ id: '', name: '', description: '' }); setCategoryModalOpen(false); };
  const saveCategory = async () => { if (!categoryForm.name.trim()) { toast.error('Escribe el nombre de la categoría.'); return; } setSaving(true); try { if (categoryForm.id) await restaurantService.updateCategory(categoryForm.id, { name: categoryForm.name.trim(), description: categoryForm.description.trim() || null }); else await restaurantService.createCategory({ name: categoryForm.name.trim(), description: categoryForm.description.trim() || undefined }); resetCategory(); toast.success(categoryForm.id ? 'Categoría actualizada.' : 'Categoría creada.'); await onSaved(); } catch (error: unknown) { toast.error(getApiErrorMessage(error, 'No se pudo guardar la categoría.')); } finally { setSaving(false); } };
  const archiveCategory = async (category: RestaurantMenuCategory) => { if (!canEdit || !window.confirm(`¿Ocultar la categoría “${category.name}” del menú?`)) return; try { await restaurantService.updateCategory(category.id, { isActive: false }); setSelectedCategoryId('ALL'); toast.success('Categoría ocultada.'); await onSaved(); } catch (error: unknown) { toast.error(getApiErrorMessage(error, 'No se pudo ocultar la categoría.')); } };
  const reorderCategory = async (category: RestaurantMenuCategory, direction: -1 | 1) => { const index = menu.findIndex((entry) => entry.id === category.id); const target = menu[index + direction]; if (!canEdit || !target) return; setSaving(true); try { await Promise.all([restaurantService.updateCategory(category.id, { sortOrder: index + direction }), restaurantService.updateCategory(target.id, { sortOrder: index })]); toast.success('Orden de categorías actualizado.'); await onSaved(); } catch (error: unknown) { toast.error(getApiErrorMessage(error, 'No se pudo reordenar la categoría.')); } finally { setSaving(false); } };
  const saveItem = async () => { const price = Number(draft.price); if (!draft.categoryId || !draft.name.trim() || !Number.isFinite(price) || price < 0) { toast.error('Completa categoría, nombre y precio.'); return; } const invalidGroup = draft.options.find((group) => !group.name.trim() || !group.choices.length || group.choices.some((choice) => !choice.name.trim() || Number(choice.priceAdjustment) < 0)); if (invalidGroup) { toast.error('Completa correctamente los grupos y opciones del platillo.'); return; } setSaving(true); try { const payload = { categoryId: draft.categoryId, productId: draft.productId.trim() || null, name: draft.name.trim(), description: draft.description.trim() || null, price, taxRate: Number(draft.taxRate) || 0, prepStation: draft.prepStation, imageUrl: draft.imageUrl.trim() || null, options: draft.options, metadata: metadataFromDraft(draft), isAvailable: draft.state === 'AVAILABLE', isFeatured: draft.featured }; let savedItem: RestaurantMenuItem | undefined; if (editingItemId) await restaurantService.updateMenuItem(editingItemId, payload); else { savedItem = await restaurantService.createMenuItem({ categoryId: draft.categoryId, ...payload }); if (savedItem?.id && draft.gallery.length) { const uploadedGallery = await Promise.all(draft.gallery.map(async (image, index) => { if (!image.startsWith('data:')) return image; const imageBlob = await (await fetch(image)).blob(); const uploaded = await storageService.uploadFile('product-image', new File([imageBlob], `menu-image-${index + 1}.png`, { type: imageBlob.type || 'image/png' }), { folder: `restaurant-menu/${savedItem.id}` }); return uploaded.url || uploaded.uri; })); const mainImage = uploadedGallery[0] || null; await restaurantService.updateMenuItem(savedItem.id, { imageUrl: mainImage, metadata: metadataFromDraft({ ...draft, imageUrl: mainImage || '', gallery: uploadedGallery }) }); } } toast.success(editingItemId ? 'Platillo actualizado.' : 'Platillo agregado a la carta.'); setView('catalog'); setEditingItemId(null); await onSaved(); } catch (error: unknown) { toast.error(getApiErrorMessage(error, 'No se pudo guardar el platillo.')); } finally { setSaving(false); } };
  const toggleItem = async (item: RestaurantMenuItem) => { if (!canEdit) return; setSaving(true); try { await restaurantService.updateMenuItem(item.id, { isAvailable: !item.isAvailable, metadata: { ...(item.metadata || {}), availability: { ...(item.metadata?.availability || {}), state: item.isAvailable ? 'HIDDEN' : 'AVAILABLE' } } }); toast.success(item.isAvailable ? 'Platillo ocultado.' : 'Platillo publicado.'); await onSaved(); } catch (error: unknown) { toast.error(getApiErrorMessage(error, 'No se pudo cambiar la disponibilidad.')); } finally { setSaving(false); } }; const duplicateItem = async (item: RestaurantMenuItem) => { if (!canCreate) return; setSaving(true); try { await restaurantService.createMenuItem({ categoryId: item.categoryId, name: `${item.name} (copia)`, description: item.description, price: Number(item.price), currency: item.currency, taxRate: Number(item.taxRate), prepStation: item.prepStation, imageUrl: item.imageUrl, options: item.options || [], metadata: item.metadata || undefined }); toast.success('Platillo duplicado.'); await onSaved(); } catch (error: unknown) { toast.error(getApiErrorMessage(error, 'No se pudo duplicar el platillo.')); } finally { setSaving(false); } };
  const addOptionGroup = () => updateDraft('options', [...draft.options, { id: `group-${crypto.randomUUID()}`, name: '', required: false, multiple: false, choices: [{ id: `choice-${crypto.randomUUID()}`, name: '', priceAdjustment: 0 }] }]); const updateOptionGroup = (groupId: string, patch: Partial<RestaurantMenuOptionGroup>) => updateDraft('options', draft.options.map((group) => group.id === groupId ? { ...group, ...patch } : group)); const addIngredient = () => updateDraft('recipeLines', [...draft.recipeLines, { id: `ingredient-${crypto.randomUUID()}`, name: '', quantity: 1, unit: 'unidad', unitCost: 0, wastePercent: 0 }]); const updateIngredient = (id: string, patch: Partial<RecipeLine>) => updateDraft('recipeLines', draft.recipeLines.map((line) => line.id === id ? { ...line, ...patch } : line));
  const saveSettings = async (nextTheme?: typeof theme, nextShowImages?: boolean, nextLanguage?: typeof language, nextPresentation?: Partial<Pick<RestaurantMenuSettings, 'showDescriptions' | 'showPrices' | 'showAllergens' | 'showFooter'>>) => { const presentation = { showDescriptions, showPrices, showAllergens, showFooter, ...nextPresentation }; setSaving(true); try { const updated = await restaurantService.updateMenuSettings({ theme: nextTheme ?? theme, showImages: nextShowImages ?? showImages, ...presentation, language: nextLanguage ?? language }); if (updated?.theme) setTheme(updated.theme); if (typeof updated?.showImages === 'boolean') setShowImages(updated.showImages); if (typeof updated?.showDescriptions === 'boolean') setShowDescriptions(updated.showDescriptions); if (typeof updated?.showPrices === 'boolean') setShowPrices(updated.showPrices); if (typeof updated?.showAllergens === 'boolean') setShowAllergens(updated.showAllergens); if (typeof updated?.showFooter === 'boolean') setShowFooter(updated.showFooter); if (updated?.language) setLanguage(updated.language); toast.success('Diseño y publicación actualizados.'); } catch (error: unknown) { toast.error(getApiErrorMessage(error, 'No se pudo guardar el diseño.')); } finally { setSaving(false); } };
  const uploadItemImage = async (file?: File) => { if (!file || !canEdit) return; const localUrl = await new Promise<string>((resolve, reject) => { const reader = new FileReader(); reader.onload = () => resolve(String(reader.result || '')); reader.onerror = () => reject(reader.error || new Error('No se pudo leer la imagen.')); reader.readAsDataURL(file); }); if (!editingItemId) { const nextGallery = [localUrl, ...draft.gallery.filter((image) => image !== draft.imageUrl)]; updateDraft('imageUrl', localUrl); updateDraft('gallery', nextGallery); toast.success('Imagen agregada. Se guardará junto con el platillo.'); return; } setSaving(true); try { const uploaded = await storageService.uploadFile('product-image', file, { folder: `restaurant-menu/${editingItemId}` }); const url = uploaded.url || uploaded.uri; const nextGallery = [url, ...draft.gallery.filter((image) => image !== draft.imageUrl && image !== url)]; const nextDraft = { ...draft, imageUrl: url, gallery: nextGallery }; updateDraft('imageUrl', url); updateDraft('gallery', nextGallery); await restaurantService.updateMenuItem(editingItemId, { imageUrl: url, metadata: metadataFromDraft(nextDraft) }); toast.success('Imagen principal actualizada.'); await onSaved(); } catch (error: unknown) { toast.error(getApiErrorMessage(error, 'No se pudo cargar la imagen.')); } finally { setSaving(false); } };
  const uploadGalleryImage = async (file?: File) => { if (!file || !canEdit) return; const localUrl = await new Promise<string>((resolve, reject) => { const reader = new FileReader(); reader.onload = () => resolve(String(reader.result || '')); reader.onerror = () => reject(reader.error || new Error('No se pudo leer la imagen.')); reader.readAsDataURL(file); }); if (!editingItemId) { const nextGallery = [...draft.gallery, localUrl]; updateDraft('gallery', nextGallery); if (!draft.imageUrl) updateDraft('imageUrl', localUrl); toast.success('Imagen agregada a la galería.'); return; } setSaving(true); try { const uploaded = await storageService.uploadFile('product-image', file, { folder: `restaurant-menu/${editingItemId}` }); const url = uploaded.url || uploaded.uri; const nextGallery = [...draft.gallery, url]; const nextDraft = { ...draft, imageUrl: draft.imageUrl || url, gallery: nextGallery }; updateDraft('gallery', nextGallery); if (!draft.imageUrl) updateDraft('imageUrl', url); await restaurantService.updateMenuItem(editingItemId, { imageUrl: nextDraft.imageUrl, metadata: metadataFromDraft(nextDraft) }); toast.success('Imagen agregada a la galería.'); await onSaved(); } catch (error: unknown) { toast.error(getApiErrorMessage(error, 'No se pudo cargar la imagen.')); } finally { setSaving(false); } };
  const removeGalleryImage = async (image: string) => { const nextGallery = draft.gallery.filter((entry) => entry !== image); const nextImage = nextGallery[0] || ''; if (!editingItemId) { updateDraft('gallery', nextGallery); updateDraft('imageUrl', nextImage); return; } setSaving(true); try { const nextDraft = { ...draft, imageUrl: nextImage, gallery: nextGallery }; updateDraft('gallery', nextGallery); updateDraft('imageUrl', nextImage); await restaurantService.updateMenuItem(editingItemId, { imageUrl: nextImage || null, metadata: metadataFromDraft(nextDraft) }); toast.success('Imagen retirada de la galería.'); await onSaved(); } catch (error: unknown) { toast.error(getApiErrorMessage(error, 'No se pudo retirar la imagen.')); } finally { setSaving(false); } };
  const uploadBrandAsset = async (file: File | undefined, kind: 'logo' | 'cover') => { if (!file || !canConfigureRestaurant) return; const localUrl = await new Promise<string>((resolve, reject) => { const reader = new FileReader(); reader.onload = () => resolve(String(reader.result || '')); reader.onerror = () => reject(reader.error || new Error('No se pudo leer la imagen.')); reader.readAsDataURL(file); }); if (kind === 'logo') setLogoPreview(localUrl); else setCoverPreview(localUrl); setSaving(true); try { const uploaded = await storageService.uploadFile('tenant-branding', file, { folder: `restaurant-menu/${kind}` }); const url = uploaded.url || uploaded.uri; if (kind === 'logo') setLogoPreview(url); else setCoverPreview(url); await restaurantService.updateConfiguration({ profile: { [kind === 'logo' ? 'logo' : 'coverImage']: url } as never }); toast.success(kind === 'logo' ? 'Logo actualizado.' : 'Portada actualizada.'); } catch (error: unknown) { toast.error(getApiErrorMessage(error, 'No se pudo sincronizar la imagen.')); } finally { setSaving(false); } };
  const saveBrandColor = async (kind: 'primaryColor' | 'accentColor', value: string) => { if (!canConfigureRestaurant) return; try { await restaurantService.updateConfiguration({ profile: { [kind]: value } as never }); toast.success('Color de la carta actualizado.'); } catch (error: unknown) { toast.error(getApiErrorMessage(error, 'No se pudo guardar el color.')); } }; const openMenuQr = async () => { if (!publicLink) { toast.error('Configura primero el enlace público.'); return; } try { setQrPreview(await QRCode.toDataURL(publicLink, { width: 720, margin: 2, color: { dark: '#01422C', light: '#FFFFFF' } })); setShowQr(true); } catch (error: unknown) { toast.error(getApiErrorMessage(error, 'No se pudo generar el QR del menú.')); } };
  const exportMenu = async (format: 'pdf' | 'xlsx') => { if (!canExport || !allItems.length) return toast.error('Agrega platillos antes de exportar.'); const rows = allItems.map(({ item, category }) => ({ Categoría: category.name, Platillo: item.name, Descripción: item.description || '', Precio: Number(item.price || 0), Moneda: item.currency, Estado: item.isAvailable ? 'Activo' : 'Oculto', Etiquetas: arrayFrom(item.metadata?.tags).join(', ') })); try { if (format === 'xlsx') { const workbook = XLSX.utils.book_new(); XLSX.utils.book_append_sheet(workbook, XLSX.utils.json_to_sheet(rows), 'Carta'); XLSX.writeFile(workbook, buildDatedDownloadFileName(['carta_restaurante'], 'xlsx')); } else await generateConfiguredReportSectionsPDF({ targetKey: 'restaurante.menu', title: 'Carta de Restaurante', sections: menu.map((category) => ({ id: category.id, title: category.name, headers: ['Platillo', 'Descripción', 'Precio', 'Estado'], rows: category.items.map((item) => [item.name, item.description || '', money(item.price, item.currency), item.isAvailable ? 'Activo' : 'Oculto']) })), fileName: buildDatedDownloadFileName(['carta_restaurante'], 'pdf'), forceNative: true }); toast.success(`Carta exportada en ${format === 'xlsx' ? 'Excel' : 'PDF'}.`); } catch (error: unknown) { toast.error(getApiErrorMessage(error, 'No se pudo exportar.')); } };
  const importMenu = async (file?: File) => { if (!file || !canCreate) return; setImporting(true); try { const parsed = await parseSpreadsheetInWorker(file); const rows = parsed.rows || []; if (rows.length < 2) throw new Error('La plantilla debe incluir encabezados y al menos un platillo.'); const headers = rows[0].map((header: unknown) => String(header || '').trim().toLowerCase()); const find = (...names: string[]) => headers.findIndex((header: string) => names.includes(header)); const categoryIndex = find('categoría', 'categoria', 'category'); const nameIndex = find('platillo', 'producto', 'nombre', 'name'); const priceIndex = find('precio', 'price'); const descriptionIndex = find('descripción', 'descripcion', 'description'); if (nameIndex < 0 || priceIndex < 0) throw new Error('La plantilla necesita las columnas Platillo y Precio.'); const categoryMap = new Map(menu.map((category) => [category.name.toLowerCase(), category.id])); let created = 0; for (const row of rows.slice(1)) { const name = String(row[nameIndex] || '').trim(); const price = Number(row[priceIndex]); if (!name || !Number.isFinite(price)) continue; const categoryName = String(row[categoryIndex] || 'General').trim() || 'General'; let categoryId = categoryMap.get(categoryName.toLowerCase()); if (!categoryId) { const category = await restaurantService.createCategory({ name: categoryName }); categoryId = category.id; categoryMap.set(categoryName.toLowerCase(), category.id); } await restaurantService.createMenuItem({ categoryId, name, price, description: descriptionIndex >= 0 ? String(row[descriptionIndex] || '') : undefined, prepStation: 'KITCHEN' }); created += 1; } toast.success(`${created} platillo(s) importado(s).`); await onSaved(); } catch (error: unknown) { toast.error(getApiErrorMessage(error, 'No se pudo importar la carta.')); } finally { setImporting(false); } };

  const themes = [{ id: 'classic' as const, label: 'Clásica', description: 'Diseño limpio y elegante, ideal para cafeterías y restaurantes.', className: 'bg-gradient-to-br from-[#123f2c] via-[#3d6b3d] to-[#d9b36c]', category: 'Clásica' }, { id: 'modern' as const, label: 'Moderna', description: 'Estilo contemporáneo con grandes imágenes y enfoque visual.', className: 'bg-gradient-to-br from-[#f5efe5] via-[#d6b78d] to-[#76533d]', category: 'Moderna' }, { id: 'elegant' as const, label: 'Elegante', description: 'Diseño sofisticado para restaurantes de alta cocina.', className: 'bg-gradient-to-br from-[#090b0d] via-[#29231e] to-[#8e6a35]', category: 'Premium' }, { id: 'retro' as const, label: 'Fast Food', description: 'Diseño dinámico y colorido para comida rápida.', className: 'bg-gradient-to-br from-[#e64718] via-[#f98c2f] to-[#fff0d0]', category: 'Casual' }, { id: 'rustic' as const, label: 'Minimalista', description: 'Diseño minimalista con enfoque en la comida.', className: 'bg-gradient-to-br from-[#f4f1e8] via-[#e6dec9] to-[#b3c2a0]', category: 'Minimalista' }, { id: 'editorial' as const, label: 'Gourmet', description: 'Diseño premium para una experiencia gastronómica.', className: 'bg-gradient-to-br from-[#101112] via-[#314337] to-[#ba933f]', category: 'Premium' }];
  const tabs: Array<{ id: EditorTab; label: string; icon: typeof BookOpen }> = [{ id: 'general', label: 'Información general', icon: BookOpen }, { id: 'prices', label: 'Precios y variantes', icon: SlidersHorizontal }, { id: 'ingredients', label: 'Ingredientes', icon: Package }, { id: 'modifiers', label: 'Modificadores', icon: Tags }, { id: 'availability', label: 'Disponibilidad', icon: Clock3 }]; const primaryButton = 'rounded-xl bg-primary text-primary-foreground hover:bg-primary/90'; const accentButton = 'rounded-xl bg-accent text-accent-foreground hover:bg-accent/90'; const filterClass = 'h-10 rounded-xl border-accent/25 bg-accent/10 text-primary';

  return <section className={`nh-menu-workspace space-y-5 ${view === 'templates' ? 'nh-menu-templates' : ''} ${view === 'catalog' ? 'nh-menu-catalog' : ''}`}>
    {view === 'catalog' && <div className="flex flex-wrap items-center justify-end gap-2 rounded-2xl border border-border/60 bg-card p-3 shadow-sm"><Button variant="outline" onClick={() => window.open(publicLink || '#', '_blank')} disabled={!publicLink}><Globe2 className="size-4" />Vista previa del menú</Button><DropdownMenu><DropdownMenuTrigger asChild><Button variant="outline"><Download className="size-4" />Exportar<ChevronDown className="size-3.5" /></Button></DropdownMenuTrigger><DropdownMenuContent align="end" className="rounded-xl"><DropdownMenuItem onClick={() => void exportMenu('pdf')}><FileText className="mr-2 size-4" />PDF para imprimir</DropdownMenuItem><DropdownMenuItem onClick={() => void exportMenu('xlsx')}><FileSpreadsheet className="mr-2 size-4" />Excel</DropdownMenuItem></DropdownMenuContent></DropdownMenu><Button variant="outline" onClick={() => void openMenuQr()}><QrCode className="size-4" />Gestionar QR</Button><Button variant="outline" onClick={() => setView('templates')}><BookOpen className="size-4" />Diseño de carta</Button><Button variant="outline" onClick={() => setView('design')}><Globe2 className="size-4" />Editor visual</Button><Button className={primaryButton} onClick={() => openEditor()} disabled={!canCreate}><Plus className="size-4" />Agregar platillo</Button></div>}
    {view === 'catalog' && <div className="grid gap-5 xl:grid-cols-[250px_minmax(0,1fr)]"><aside className="rounded-2xl border border-border/60 bg-card p-3 shadow-sm"><div className="flex items-center justify-between gap-2"><p className="font-serif text-xl font-medium italic text-primary">Categorías</p><Button className={accentButton} size="sm" onClick={() => openCategoryEditor()} disabled={!canCreate}><Plus className="size-4" />Agregar categoría</Button></div><button type="button" onClick={() => setSelectedCategoryId('ALL')} className={`mt-4 flex w-full items-center justify-between rounded-xl px-3 py-2.5 text-left text-sm font-black ${selectedCategoryId === 'ALL' ? 'bg-accent text-accent-foreground' : 'bg-accent/10 text-primary hover:bg-accent/20'}`}><span className="flex items-center gap-2">{categoryIcon()}Todas</span><Badge className={selectedCategoryId === 'ALL' ? 'bg-white/20 text-white' : 'bg-accent/20 text-primary'}>{allItems.length}</Badge></button><div className="mt-2 max-h-[360px] space-y-1 overflow-y-auto pr-1">{menu.map((category, index) => <div key={category.id} className={`flex items-center gap-1 rounded-xl ${selectedCategoryId === category.id ? 'bg-accent/15 text-primary' : 'hover:bg-muted/60'}`}><button type="button" onClick={() => setSelectedCategoryId(category.id)} className="flex min-w-0 flex-1 items-center justify-between rounded-xl px-3 py-2.5 text-left text-sm"><span className="flex min-w-0 items-center gap-2 truncate font-semibold">{categoryIcon()}<span className="truncate">{category.name}</span></span><span className="ml-2 text-xs font-black text-accent">{category.items.length}</span></button>{selectedCategoryId === category.id && <div className="flex pr-1"><button type="button" onClick={() => void reorderCategory(category, -1)} disabled={index === 0 || saving} className="rounded p-1 text-muted-foreground hover:bg-muted" aria-label="Subir categoría"><ArrowUp className="size-3" /></button><button type="button" onClick={() => void reorderCategory(category, 1)} disabled={index === menu.length - 1 || saving} className="rounded p-1 text-muted-foreground hover:bg-muted" aria-label="Bajar categoría"><ArrowDown className="size-3" /></button></div>}</div>)}</div></aside><div className="min-w-0 space-y-5">{selectedCategory && <div className="flex flex-wrap items-center justify-between gap-3 rounded-2xl border border-accent/25 bg-accent/5 p-4"><div className="flex items-center gap-3"><span className="flex size-11 items-center justify-center rounded-2xl bg-accent/20 text-primary">{categoryIcon()}</span><div><h2 className="font-serif text-2xl font-medium italic text-primary">{selectedCategory.name}</h2><p className="text-xs text-muted-foreground">{selectedCategory.description || 'Deliciosas opciones para comenzar el día.'}</p></div></div><div className="flex flex-wrap gap-2"><Button variant="outline" size="sm" onClick={() => openCategoryEditor(selectedCategory)} disabled={!canEdit}><Pencil className="size-3.5" />Editar categoría</Button><Button variant="outline" size="sm" onClick={() => void reorderCategory(selectedCategory, -1)} disabled={!canEdit}><SlidersHorizontal className="size-3.5" />Reordenar</Button><Button variant="outline" size="sm" className="text-destructive hover:text-destructive" onClick={() => void archiveCategory(selectedCategory)} disabled={!canEdit}><Trash2 className="size-3.5" />Ocultar</Button></div></div>}<div className="grid gap-3 md:grid-cols-2 2xl:grid-cols-3">{visibleItems.map(({ item, category }) => <article key={item.id} className="overflow-hidden rounded-2xl border border-border/60 bg-card shadow-sm transition hover:-translate-y-0.5 hover:border-accent/50"><div className="relative aspect-[1.8] bg-muted">{item.imageUrl ? <img src={item.imageUrl} alt={item.name} className="size-full object-cover" /> : <div className="flex size-full items-center justify-center text-primary"><span className="rounded-2xl bg-accent/20 p-5">{categoryIcon()}</span></div>}<Badge className={`absolute left-3 top-3 ${item.isAvailable ? 'bg-accent text-accent-foreground' : 'bg-slate-700 text-white'}`}>{item.isAvailable ? 'Activo' : 'Oculto'}</Badge></div><div className="p-3.5"><div className="flex items-start justify-between gap-2"><div className="min-w-0"><p className="truncate font-black">{item.name}</p><p className="mt-1 truncate text-xs text-muted-foreground">{category.name} · {stationLabel(item.prepStation)}</p></div><span className="shrink-0 font-black text-accent">{money(item.price, item.currency)}</span></div><div className="mt-3 flex flex-wrap gap-1.5">{arrayFrom(item.metadata?.tags).slice(0, 3).map((tag) => <Badge key={tag} variant="secondary" className="rounded-md bg-accent/15 text-[10px] text-primary">{tag}</Badge>)}</div><div className="mt-3 flex items-center justify-between border-t border-border/60 pt-3"><div className="flex gap-1"><Button variant="ghost" size="icon" className="size-8" onClick={() => openEditor(item, category.id)} aria-label={`Editar ${item.name}`}><Pencil className="size-3.5" /></Button><Button variant="ghost" size="icon" className="size-8" onClick={() => void duplicateItem(item)} aria-label={`Duplicar ${item.name}`} disabled={!canCreate || saving}><Copy className="size-3.5" /></Button><Button variant="ghost" size="icon" className="size-8 text-primary" onClick={() => void toggleItem(item)} aria-label={item.isAvailable ? `Ocultar ${item.name}` : `Publicar ${item.name}`} disabled={!canEdit || saving}>{item.isAvailable ? <EyeOff className="size-3.5" /> : <Eye className="size-3.5" />}</Button></div><span className="text-[10px] font-bold uppercase tracking-widest text-muted-foreground">{item.metadata?.availability?.state === 'SOLD_OUT' ? 'Agotado' : item.isAvailable ? 'Publicado' : 'Oculto'}</span></div></div></article>)}</div><div className="grid gap-5 xl:grid-cols-[minmax(0,1fr)_280px]"><div className="overflow-hidden rounded-2xl border border-border/60 bg-card shadow-sm"><div className="flex flex-wrap items-center justify-between gap-3 border-b border-border/60 p-4"><div><p className="font-serif text-xl font-medium italic text-primary">Todos los platillos</p><p className="mt-1 text-xs text-muted-foreground">Consulta, filtra y administra todo el contenido de tu carta.</p></div><span className="rounded-full bg-accent/15 px-2 py-1 text-xs font-black text-primary">{visibleItems.length} resultados</span></div><div className="flex flex-wrap items-center gap-2 border-b border-border/60 p-3"><div className="relative min-w-64 flex-1"><Search className="absolute left-3 top-1/2 size-4 -translate-y-1/2 text-muted-foreground" /><Input className="h-10 rounded-xl pl-9" placeholder="Buscar por nombre, ingredientes o etiquetas…" value={search} onChange={(event) => setSearch(event.target.value)} /></div><input ref={fileInputRef} type="file" accept=".xlsx,.xls,.csv" className="hidden" onChange={(event) => { void importMenu(event.target.files?.[0]); event.currentTarget.value = ''; }} /><Button type="button" variant="outline" onClick={() => fileInputRef.current?.click()} disabled={!canCreate || importing}><Upload className="size-4" />{importing ? 'Importando…' : 'Importar carta'}</Button><select aria-label="Filtrar por estado" className={filterClass} value={statusFilter} onChange={(event) => setStatusFilter(event.target.value)}><option value="ALL">Todos los estados</option><option value="AVAILABLE">Activos</option><option value="SOLD_OUT">Agotados</option><option value="HIDDEN">Ocultos</option></select><select aria-label="Filtrar por tipo" className={filterClass} value={typeFilter} onChange={(event) => setTypeFilter(event.target.value)}><option value="ALL">Todos los tipos</option><option value="DRINK">Bebidas</option><option value="STARTER">Entradas</option><option value="MAIN">Platos fuertes</option><option value="DESSERT">Postres</option></select><select aria-label="Filtrar por etiqueta" className={filterClass} value={tagFilter} onChange={(event) => setTagFilter(event.target.value)}><option value="ALL">Todas las etiquetas</option>{allTags.map((tag) => <option key={tag} value={tag}>{tag}</option>)}</select><select aria-label="Ordenar platillos" className={filterClass} value={sortFilter} onChange={(event) => setSortFilter(event.target.value)}><option value="recent">Más recientes</option><option value="name">Nombre</option><option value="price">Precio</option></select></div><div className="overflow-x-auto"><table className="w-full min-w-[680px] text-left text-sm"><thead className="bg-muted/30 text-xs uppercase tracking-wider text-muted-foreground"><tr><th className="px-4 py-3 font-black">Platillo</th><th className="px-4 py-3 font-black">Categoría</th><th className="px-4 py-3 font-black">Precio</th><th className="px-4 py-3 font-black">Etiquetas</th><th className="px-4 py-3 font-black">Estado</th><th className="px-4 py-3 font-black">Acciones</th></tr></thead><tbody className="divide-y divide-border/60">{visibleItems.slice(0, 12).map(({ item, category }) => <tr key={`table-${item.id}`} className="hover:bg-muted/20"><td className="px-4 py-3"><div className="flex items-center gap-3"><div className="size-9 overflow-hidden rounded-lg bg-accent/10">{item.imageUrl ? <img src={item.imageUrl} alt="" className="size-full object-cover" /> : <Utensils className="m-2 size-5 text-primary" />}</div><span className="font-bold">{item.name}</span></div></td><td className="px-4 py-3 text-muted-foreground">{category.name}</td><td className="px-4 py-3 font-black text-accent">{money(item.price, item.currency)}</td><td className="px-4 py-3"><div className="flex max-w-44 flex-wrap gap-1">{arrayFrom(item.metadata?.tags).slice(0, 2).map((tag) => <Badge key={tag} variant="secondary" className="rounded-full bg-accent/15 text-[10px] text-primary">{tag}</Badge>)}</div></td><td className="px-4 py-3"><Badge className={item.isAvailable ? 'rounded-full bg-accent/15 text-primary' : 'rounded-full bg-muted text-muted-foreground'}>{item.isAvailable ? 'Activo' : 'Oculto'}</Badge></td><td className="px-4 py-3"><div className="flex gap-1"><Button variant="ghost" size="icon" className="size-8" onClick={() => openEditor(item, category.id)} aria-label={`Editar ${item.name}`}><Pencil className="size-3.5" /></Button><Button variant="ghost" size="icon" className="size-8" onClick={() => void duplicateItem(item)} disabled={!canCreate || saving} aria-label={`Duplicar ${item.name}`}><Copy className="size-3.5" /></Button></div></td></tr>)}</tbody></table></div></div><aside className="rounded-2xl border border-accent/20 bg-accent/5 p-5"><div className="flex items-center gap-2"><Tags className="size-5 text-primary" /><p className="font-serif text-xl font-medium italic text-primary">Etiquetas</p></div><p className="mt-2 text-sm leading-5 text-muted-foreground">Organiza, destaca y filtra tus platillos en el menú.</p><div className="mt-4 flex flex-wrap gap-2">{allTags.slice(0, 8).map((tag) => <Badge key={tag} variant="secondary" className="rounded-full bg-accent/20 text-primary">{tag}</Badge>)}</div><Button className={`mt-5 w-full ${accentButton}`} onClick={() => setTagFilter('ALL')}><Tags className="size-4" />Gestionar etiquetas</Button></aside></div></div></div>}
    {view === 'templates' && <div className="space-y-5"><div className="flex flex-wrap items-start justify-between gap-3"><div><button type="button" onClick={() => setView('catalog')} className="mb-3 flex items-center gap-2 text-xs font-bold text-muted-foreground hover:text-primary"><ArrowLeft className="size-4" />Volver a Carta y menú</button><p className="text-xs font-black uppercase tracking-widest text-primary">Restaurante · Diseño</p><h2 className="mt-1 font-serif text-3xl font-medium italic text-primary">Diseño de carta y plantillas</h2><p className="mt-1 text-sm text-muted-foreground">Selecciona una plantilla para la carta de tu restaurante. Podrás personalizarla después.</p></div><Button className={primaryButton} onClick={() => setView('design')}><Globe2 className="size-4" />Editor visual</Button></div><div className="grid gap-2 sm:grid-cols-2 lg:grid-cols-4"><button type="button" onClick={() => setTemplateFilter('Todas las plantillas')} className={`rounded-xl border px-4 py-2.5 text-xs font-black transition ${templateFilter === 'Todas las plantillas' ? 'border-primary bg-primary text-primary-foreground' : 'border-border/60 bg-card text-muted-foreground hover:border-accent/50'}`}>Todas las plantillas</button><label className="flex items-center justify-between gap-2 rounded-xl border border-border/60 bg-card px-3 py-2 text-xs font-black text-primary">Estilo<select className="h-8 rounded-lg border border-accent/30 bg-accent/10 px-2 text-xs font-bold text-primary" value={templateFilter} onChange={(event) => setTemplateFilter(event.target.value)}><option value="Todas las plantillas">Todos</option><option value="Clásica">Clásica</option><option value="Moderna">Moderna</option><option value="Elegante">Elegante</option><option value="Fast Food">Fast Food</option><option value="Minimalista">Minimalista</option><option value="Gourmet">Gourmet</option></select></label><label className="flex items-center justify-between gap-2 rounded-xl border border-border/60 bg-card px-3 py-2 text-xs font-black text-primary">Idioma<select className="h-8 rounded-lg border border-accent/30 bg-accent/10 px-2 text-xs font-bold text-primary" value={languageFilter} onChange={(event) => { const value = event.target.value; setLanguageFilter(value); if (value === 'Español') void saveSettings(undefined, undefined, 'ES'); if (value === 'Español + English') void saveSettings(undefined, undefined, 'BOTH'); }}><option>Todas</option><option>Español</option><option>Español + English</option></select></label><label className="flex items-center justify-between gap-2 rounded-xl border border-border/60 bg-card px-3 py-2 text-xs font-black text-primary">Optimizada para<select className="h-8 rounded-lg border border-accent/30 bg-accent/10 px-2 text-xs font-bold text-primary" value={optimizedFilter} onChange={(event) => setOptimizedFilter(event.target.value)}><option>Todos</option><option>Café</option><option>Restaurante</option><option>Delivery</option></select></label></div><div className="grid gap-4 md:grid-cols-2 xl:grid-cols-3">{themes.filter((item) => { const styleMatch = templateFilter === 'Todas las plantillas' || item.label === templateFilter || item.category === templateFilter; const languageMatch = languageFilter === 'Todas' || languageFilter === 'Español' || languageFilter === 'Español + English'; const optimizedMatch = optimizedFilter === 'Todos' || (optimizedFilter === 'Café' && ['Clásica', 'Moderna'].includes(item.label)) || (optimizedFilter === 'Restaurante' && item.label !== 'Fast Food') || (optimizedFilter === 'Delivery' && ['Clásica', 'Moderna', 'Fast Food'].includes(item.label)); return styleMatch && languageMatch && optimizedMatch; }).map((item) => <button key={item.id} type="button" onClick={() => void saveSettings(item.id)} disabled={!canEdit || saving} className={`overflow-hidden rounded-2xl border-2 bg-card text-left shadow-sm transition hover:-translate-y-0.5 ${theme === item.id ? 'border-accent ring-2 ring-accent/20' : 'border-border/60 hover:border-primary/40'}`}><div className={`relative h-44 overflow-hidden p-4 ${item.className}`}><div className="absolute inset-x-7 top-5 rounded-xl bg-white/90 p-3 shadow-xl"><p className="text-center font-serif text-sm font-bold italic text-[#01422C]">{item.label === 'Fast Food' ? 'Fast Food' : item.label === 'Gourmet' ? 'Gourmet Menu' : 'Nuestro menú'}</p><div className="mt-3 grid grid-cols-3 gap-2">{[0, 1, 2].map((previewIndex) => <span key={previewIndex} className="nh-template-preview-photo h-14 rounded-lg bg-[#d9b36c]/80" style={previewImages[previewIndex] ? { backgroundImage: `url(\"${previewImages[previewIndex]}\")` } : undefined } />)}</div><div className="mt-2 h-1.5 w-2/3 rounded-full bg-[#01422C]/40" /></div><span className="absolute bottom-3 left-4 rounded-full bg-black/35 px-2 py-1 text-[10px] font-black uppercase tracking-widest text-white">{theme === item.id ? 'Seleccionada' : item.label}</span></div><div className="p-4"><p className="font-black">{item.label}</p><p className="mt-1 text-xs leading-5 text-muted-foreground">{item.description}</p><Badge className="mt-3 rounded-full bg-accent/15 text-primary">{item.category === 'Premium' ? 'Premium' : item.category}</Badge></div></button>)}</div><div className="flex flex-col gap-4 rounded-2xl border border-accent/30 bg-accent/5 p-4 sm:flex-row sm:items-center sm:justify-between"><div className="flex items-center gap-4"><div className={`h-20 w-28 shrink-0 rounded-xl ${themes.find((item) => item.id === theme)?.className || ''}`} /><div><p className="text-xs font-black uppercase tracking-widest text-muted-foreground">Plantilla seleccionada</p><p className="font-serif text-2xl font-medium italic text-primary">{themes.find((item) => item.id === theme)?.label}</p><p className="text-sm text-muted-foreground">{themes.find((item) => item.id === theme)?.description}</p></div></div><Button className={primaryButton} onClick={() => setView('design')}><Check className="size-4" />Continuar con la edición</Button></div></div>}
    {view === 'editor' && <div className="space-y-5"><div className="flex flex-wrap items-start justify-between gap-3"><div><button type="button" onClick={() => setView('catalog')} className="mb-2 flex items-center gap-2 text-xs font-bold text-muted-foreground hover:text-primary"><ArrowLeft className="size-4" />Carta y menú</button><h2 className="font-serif text-4xl font-medium italic text-primary">Editar platillo</h2><p className="mt-1 text-sm text-muted-foreground">Configura la información, precios y opciones de este platillo.</p></div><div className="flex flex-wrap gap-2"><Button variant="outline" onClick={() => window.open(publicLink || '#', '_blank')} disabled={!publicLink}><Globe2 className="size-4" />Ver menú público</Button><Button className={primaryButton} onClick={() => void saveItem()} disabled={saving || (!editingItemId ? !canCreate : !canEdit)}><Check className="size-4" />{saving ? 'Guardando…' : 'Guardar cambios'}</Button></div></div><div className="flex gap-1 overflow-x-auto rounded-2xl border border-border/60 bg-card p-1.5">{tabs.map(({ id, label: tabLabel, icon: Icon }) => <button key={id} type="button" onClick={() => setEditorTab(id)} className={`flex min-w-max items-center gap-2 rounded-xl border-b-2 px-4 py-3 text-xs font-black transition ${editorTab === id ? 'border-accent bg-accent/10 text-primary' : 'border-transparent text-muted-foreground hover:bg-muted/60'}`}><Icon className={`size-4 ${editorTab === id ? 'text-accent' : 'text-muted-foreground'}`} />{tabLabel}</button>)}</div><div className="grid gap-5 xl:grid-cols-[minmax(0,1.5fr)_340px]"><div className="rounded-2xl border border-border/60 bg-card p-4 shadow-sm sm:p-5">
      {editorTab === 'general' && <div className="nh-menu-editor-general space-y-5"><DishGallery draft={draft} imageInputRef={imageInputRef} galleryInputRef={galleryInputRef} canEdit={canEdit} saving={saving} uploadItemImage={uploadItemImage} uploadGalleryImage={uploadGalleryImage} removeGalleryImage={removeGalleryImage} /><InventoryBindingFields draft={draft} onChange={(patch) => setDraft((current) => ({ ...current, ...patch }))} /><RecipeBindingFields draft={draft} onChange={(patch) => setDraft((current) => ({ ...current, ...patch }))} /><div className="grid gap-4 md:grid-cols-2"><label className="text-sm font-bold"><span>Nombre del platillo *</span><Input className="mt-2" value={draft.name} onChange={(event) => updateDraft('name', event.target.value)} placeholder="Ej. Café Latte" /></label><label className="text-sm font-bold"><span>Categoría *</span><div className="relative mt-2"><span className="pointer-events-none absolute left-3 top-1/2 -translate-y-1/2 text-primary">{categoryIcon(menu.find((category) => category.id === draft.categoryId)?.name || '')}</span><select className="h-10 w-full rounded-xl border border-input bg-background pl-10 pr-3 text-sm" value={draft.categoryId} onChange={(event) => updateDraft('categoryId', event.target.value)}>{menu.map((category) => <option key={category.id} value={category.id}>{category.name}</option>)}</select></div></label><label className="text-sm font-bold md:col-span-2"><span>Descripción *</span><textarea className="mt-2 min-h-24 w-full rounded-xl border border-input bg-background px-3 py-2 text-sm" value={draft.description} onChange={(event) => updateDraft('description', event.target.value)} placeholder="Descripción breve y atractiva" /></label>{language === 'BOTH' && <><label className="text-sm font-bold"><span>Nombre en inglés</span><Input className="mt-2" value={draft.nameEn} onChange={(event) => updateDraft('nameEn', event.target.value)} placeholder="Opcional · Latte" /></label><label className="text-sm font-bold"><span>Descripción en inglés</span><textarea className="mt-2 min-h-20 w-full rounded-xl border border-input bg-background px-3 py-2 text-sm" value={draft.descriptionEn} onChange={(event) => updateDraft('descriptionEn', event.target.value)} placeholder="Opcional · Descripción en inglés" /></label></>}</div><div className="grid gap-4 md:grid-cols-2"><TagInput label="Etiquetas" values={draft.tags} onChange={(values) => updateDraft('tags', values)} placeholder="Popular + Enter" /><TagInput label="Alérgenos" values={draft.allergens} onChange={(values) => updateDraft('allergens', values)} placeholder="Lácteos + Enter" /></div><div className="grid gap-4 md:grid-cols-2"><label className="text-sm font-bold"><span>Precio *</span><div className="mt-2 flex"><span className="flex items-center rounded-l-xl border border-r-0 border-input bg-muted px-3 text-sm">C$</span><Input className="rounded-l-none" type="number" min="0" step="0.01" value={draft.price} onChange={(event) => updateDraft('price', event.target.value)} /></div></label><label className="text-sm font-bold"><span>Tipo de platillo *</span><div className="relative mt-2"><span className="pointer-events-none absolute left-3 top-1/2 -translate-y-1/2 text-primary">{dishTypeIcon(draft.dishType)}</span><select className="h-10 w-full rounded-xl border border-input bg-background pl-10 pr-3 text-sm" value={draft.dishType} onChange={(event) => updateDraft('dishType', event.target.value as DishType)}><option value="DRINK">Bebida</option><option value="STARTER">Entrada</option><option value="MAIN">Plato fuerte</option><option value="DESSERT">Postre</option></select></div></label><label className="flex items-center justify-between rounded-xl border border-border/60 p-3 text-sm font-bold md:col-span-2"><span>Estado del platillo <small className="block font-normal text-muted-foreground">Visible en el menú público.</small></span><button type="button" role="switch" aria-checked={draft.state === 'AVAILABLE'} onClick={() => updateDraft('state', draft.state === 'AVAILABLE' ? 'HIDDEN' : 'AVAILABLE')} className={'nh-editor-switch relative h-6 w-11 rounded-full ' + (draft.state === 'AVAILABLE' ? 'bg-accent' : 'bg-muted')}><span className={'absolute top-0.5 size-5 rounded-full bg-white shadow transition-all ' + (draft.state === 'AVAILABLE' ? 'left-[22px]' : 'left-0.5')} /></button></label><label className="text-sm font-bold"><span>Tiempo de preparación</span><Input className="mt-2" type="number" min="0" value={draft.prepMinutes} onChange={(event) => updateDraft('prepMinutes', event.target.value)} /><small className="mt-1 block text-xs font-normal text-muted-foreground">Minutos estimados para operación.</small></label><label className="text-sm font-bold"><span>Estación</span><select className="mt-2 h-10 w-full rounded-xl border border-input bg-background px-3 text-sm" value={draft.prepStation} onChange={(event) => updateDraft('prepStation', event.target.value)}><option value="KITCHEN">Cocina</option><option value="GRILL">Parrilla</option><option value="BAR">Barra</option><option value="DESSERTS">Postres</option></select></label></div></div>}
      {editorTab === 'prices' && <div className="space-y-5"><div><p className="font-serif text-xl font-medium italic text-primary">Tipo de precio</p><p className="text-sm text-muted-foreground">Elige cómo se venderá este platillo en tu menú.</p></div><div className="grid gap-3 md:grid-cols-3">{[{ id: 'single', label: 'Precio único', description: 'Un solo precio para el platillo.' }, { id: 'sizes', label: 'Variantes de tamaño', description: 'Diferentes tamaños con precios individuales.' }, { id: 'custom', label: 'Variantes personalizadas', description: 'Crea variantes con nombres y precios propios.' }].map((mode) => <button key={mode.id} type="button" onClick={() => { if (mode.id !== 'single' && !draft.options.some((group) => group.name === 'Tamaño')) updateDraft('options', [...draft.options, { id: `group-${crypto.randomUUID()}`, name: 'Tamaño', required: true, multiple: false, choices: [{ id: `choice-${crypto.randomUUID()}`, name: '8 oz', priceAdjustment: 0 }] }]); }} className={`rounded-2xl border p-4 text-left ${mode.id === (draft.options.some((group) => group.name === 'Tamaño') ? 'sizes' : 'single') ? 'border-accent bg-accent/10 ring-2 ring-accent/15' : 'border-border/60 hover:border-accent/50'}`}><span className="flex size-9 items-center justify-center rounded-xl bg-accent/20 text-primary"><SlidersHorizontal className="size-5" /></span><p className="mt-3 font-black">{mode.label}</p><p className="mt-1 text-xs text-muted-foreground">{mode.description}</p></button>)}</div><div className="flex items-center justify-between"><div><p className="font-black text-primary">Variantes de tamaño</p><p className="text-sm text-muted-foreground">Configura tamaños y sus precios.</p></div><Button className={accentButton} size="sm" onClick={() => { const group = draft.options.find((entry) => entry.name === 'Tamaño'); if (group) updateOptionGroup(group.id, { choices: [...group.choices, { id: `choice-${crypto.randomUUID()}`, name: '', priceAdjustment: 0 }] }); else addOptionGroup(); }}><Plus className="size-4" />Agregar tamaño</Button></div><div className="overflow-x-auto rounded-2xl border border-border/60"><table className="w-full min-w-[650px] text-sm"><thead className="bg-muted/30 text-xs text-muted-foreground"><tr><th className="px-3 py-3 text-left">Tamaño</th><th className="px-3 py-3 text-left">Nombre en menú</th><th className="px-3 py-3 text-left">Precio adicional</th><th className="px-3 py-3 text-left">Acciones</th></tr></thead><tbody>{(draft.options.find((entry) => entry.name === 'Tamaño')?.choices || []).map((choice) => <tr key={choice.id} className="border-t border-border/60"><td className="px-3 py-2"><Utensils className="size-4 text-primary" /></td><td className="px-3 py-2"><Input value={choice.name} onChange={(event) => { const group = draft.options.find((entry) => entry.name === 'Tamaño'); if (group) updateOptionGroup(group.id, { choices: group.choices.map((current) => current.id === choice.id ? { ...current, name: event.target.value } : current) }); }} /></td><td className="px-3 py-2"><Input type="number" min="0" step="0.01" value={choice.priceAdjustment} onChange={(event) => { const group = draft.options.find((entry) => entry.name === 'Tamaño'); if (group) updateOptionGroup(group.id, { choices: group.choices.map((current) => current.id === choice.id ? { ...current, priceAdjustment: Number(event.target.value) || 0 } : current) }); }} /></td><td className="px-3 py-2"><Button variant="ghost" size="icon" onClick={() => { const group = draft.options.find((entry) => entry.name === 'Tamaño'); if (group && group.choices.length > 1) updateOptionGroup(group.id, { choices: group.choices.filter((current) => current.id !== choice.id) }); }}><Trash2 className="size-4 text-destructive" /></Button></td></tr>)}</tbody></table></div><div className="rounded-xl bg-sky-50 p-3 text-xs text-sky-800">Los precios incluyen impuestos según la tasa configurada en este platillo.</div></div>}
      {editorTab === 'ingredients' && <div className="space-y-5"><div><p className="font-serif text-xl font-medium italic text-primary">Receta e inventario</p><p className="text-sm text-muted-foreground">Configura cómo se descuenta el inventario y los ingredientes de cada porción.</p></div><div className="grid gap-3 md:grid-cols-3">{([{ id: 'FINISHED_PRODUCT' as const, label: 'Producto terminado', description: 'Descuenta una unidad del inventario.' }, { id: 'RECIPE' as const, label: 'Receta', description: 'Descuenta los insumos por porción.' }, { id: 'COMPONENTS' as const, label: 'Armable por componentes', description: 'Descuenta según lo que el cliente elija.' }, { id: 'NONE' as const, label: 'Sin inventario', description: 'Vende el platillo sin descontar existencias.' }]).map((mode) => <button type="button" key={mode.id} onClick={() => updateDraft('inventoryMode', mode.id)} className={`rounded-2xl border p-4 text-left ${draft.inventoryMode === mode.id ? 'border-accent bg-accent/10 ring-2 ring-accent/15' : 'border-border/60 hover:border-accent/50'}`}><span className="flex size-9 items-center justify-center rounded-xl bg-accent/20 text-primary"><Boxes className="size-5" /></span><p className="mt-3 font-black">{mode.label}</p><p className="mt-1 text-xs text-muted-foreground">{mode.description}</p></button>)}</div><div className="grid gap-4 md:grid-cols-2"><label className="text-sm font-bold">¿Cuándo descontar inventario?<select className="mt-2 h-10 w-full rounded-xl border border-input bg-background px-3 text-sm" value={draft.deductWhen} onChange={(event) => updateDraft('deductWhen', event.target.value as Draft['deductWhen'])}><option value="ORDER_CONFIRMED">Al confirmar el pedido</option><option value="SENT_TO_KITCHEN">Al enviar a cocina</option><option value="ITEM_PREPARED">Al marcar como preparado</option><option value="PAID">Al cobrar</option></select></label><label className="text-sm font-bold">Comportamiento con stock bajo<select className="mt-2 h-10 w-full rounded-xl border border-input bg-background px-3 text-sm" value={draft.shortageBehavior} onChange={(event) => updateDraft('shortageBehavior', event.target.value as Draft['shortageBehavior'])}><option value="WARN">Mostrar advertencia, pero permitir la venta</option><option value="BLOCK">Bloquear la venta</option><option value="ALLOW">Permitir y registrar faltante</option></select></label></div>{draft.inventoryMode === 'RECIPE' && <div className="overflow-x-auto rounded-2xl border border-border/60"><div className="flex items-center justify-between border-b border-border/60 p-4"><div><p className="font-black text-primary">Ingredientes de la receta</p><p className="text-xs text-muted-foreground">Costos por porción, merma y unidades.</p></div><Button className={accentButton} size="sm" onClick={addIngredient}><Plus className="size-4" />Agregar insumo</Button></div><table className="w-full min-w-[720px] text-sm"><thead className="bg-muted/30 text-xs text-muted-foreground"><tr><th className="px-3 py-3 text-left">Insumo</th><th className="px-3 py-3 text-left">Cantidad</th><th className="px-3 py-3 text-left">Unidad</th><th className="px-3 py-3 text-left">Costo unitario</th><th className="px-3 py-3 text-left">Merma</th><th className="px-3 py-3 text-left">Subtotal</th><th /></tr></thead><tbody>{draft.recipeLines.map((line) => <tr key={line.id} className="border-t border-border/60"><td className="px-3 py-2"><Input placeholder="Café espresso" value={line.name} onChange={(event) => updateIngredient(line.id, { name: event.target.value })} /></td><td className="px-3 py-2"><Input type="number" min="0" step="0.01" value={line.quantity} onChange={(event) => updateIngredient(line.id, { quantity: Number(event.target.value) || 0 })} /></td><td className="px-3 py-2"><Input value={line.unit} onChange={(event) => updateIngredient(line.id, { unit: event.target.value })} /></td><td className="px-3 py-2"><Input type="number" min="0" step="0.01" value={line.unitCost} onChange={(event) => updateIngredient(line.id, { unitCost: Number(event.target.value) || 0 })} /></td><td className="px-3 py-2"><Input type="number" min="0" value={line.wastePercent} onChange={(event) => updateIngredient(line.id, { wastePercent: Number(event.target.value) || 0 })} /></td><td className="px-3 py-2 font-black text-accent">{money(line.quantity * line.unitCost * (1 + line.wastePercent / 100))}</td><td className="px-3 py-2"><Button variant="ghost" size="icon" onClick={() => updateDraft('recipeLines', draft.recipeLines.filter((current) => current.id !== line.id))}><Trash2 className="size-4 text-destructive" /></Button></td></tr>)}</tbody></table>{!draft.recipeLines.length && <p className="p-8 text-center text-sm text-muted-foreground">Agrega los insumos de la receta para calcular costos.</p>}</div>}<label className="flex items-center justify-between rounded-xl border border-border/60 p-3 text-sm font-bold"><span>Permitir sustituciones de insumos<small className="block font-normal text-muted-foreground">Permite alternativas cuando no haya stock.</small></span><input type="checkbox" checked={draft.allowSubstitutions} onChange={(event) => updateDraft('allowSubstitutions', event.target.checked)} /></label></div>}
      {editorTab === 'modifiers' && <div className="space-y-4"><div className="flex flex-wrap items-center justify-between gap-2"><div><p className="font-serif text-xl font-medium italic text-primary">Grupos de modificadores</p><p className="text-sm text-muted-foreground">Agrega y organiza tamaños, extras y preferencias.</p></div><Button className={accentButton} size="sm" onClick={addOptionGroup} disabled={!canEdit && Boolean(editingItemId)}><Plus className="size-4" />Agregar grupo</Button></div>{draft.options.map((group) => <div key={group.id} className="rounded-2xl border border-border/60 p-4"><div className="grid gap-3 md:grid-cols-[minmax(0,1fr)_auto_auto_auto]"><Input placeholder="Ej. Tipo de leche" value={group.name} onChange={(event) => updateOptionGroup(group.id, { name: event.target.value })} /><label className="flex items-center gap-2 text-xs font-bold"><input type="checkbox" checked={Boolean(group.required)} onChange={(event) => updateOptionGroup(group.id, { required: event.target.checked })} />Obligatorio</label><label className="flex items-center gap-2 text-xs font-bold"><input type="checkbox" checked={Boolean(group.multiple)} onChange={(event) => updateOptionGroup(group.id, { multiple: event.target.checked })} />Múltiple</label><Button variant="ghost" size="icon" onClick={() => updateDraft('options', draft.options.filter((current) => current.id !== group.id))}><Trash2 className="size-4 text-destructive" /></Button></div><div className="mt-3 space-y-2">{group.choices.map((choice) => <div key={choice.id} className="grid gap-2 sm:grid-cols-[minmax(0,1fr)_150px_auto]"><Input placeholder="Nombre de la opción" value={choice.name} onChange={(event) => updateOptionGroup(group.id, { choices: group.choices.map((current) => current.id === choice.id ? { ...current, name: event.target.value } : current) })} /><Input type="number" min="0" step="0.01" placeholder="Adicional" value={choice.priceAdjustment} onChange={(event) => updateOptionGroup(group.id, { choices: group.choices.map((current) => current.id === choice.id ? { ...current, priceAdjustment: Number(event.target.value) || 0 } : current) })} /><Button variant="ghost" size="icon" disabled={group.choices.length <= 1} onClick={() => updateOptionGroup(group.id, { choices: group.choices.filter((current) => current.id !== choice.id) })} aria-label="Eliminar opción"><X className="size-4" /></Button></div>)}<Button variant="ghost" size="sm" onClick={() => updateOptionGroup(group.id, { choices: [...group.choices, { id: `choice-${crypto.randomUUID()}`, name: '', priceAdjustment: 0 }] })}><Plus className="size-3.5" />Agregar opción</Button></div></div>)}{!draft.options.length && <div className="rounded-2xl border border-dashed border-border/70 p-8 text-center text-sm text-muted-foreground">Este platillo se venderá con un precio único y sin modificadores.</div>}</div>}
      {editorTab === 'availability' && <div className="space-y-5"><div><p className="font-serif text-xl font-medium italic text-primary">Disponibilidad</p><p className="text-sm text-muted-foreground">Controla dónde y cuándo se puede pedir este platillo.</p></div><div className="grid gap-3 md:grid-cols-3">{([{ id: 'AVAILABLE' as const, label: 'Disponible', description: 'Se muestra y puede pedirse.' }, { id: 'SOLD_OUT' as const, label: 'Agotado', description: 'Se muestra como agotado.' }, { id: 'HIDDEN' as const, label: 'Oculto', description: 'No se muestra en ningún canal.' }]).map((state) => <button key={state.id} type="button" onClick={() => updateDraft('state', state.id)} className={`rounded-2xl border p-4 text-left ${draft.state === state.id ? 'border-accent bg-accent/10 ring-2 ring-accent/15' : 'border-border/60'}`}><span className="flex size-8 items-center justify-center rounded-full bg-accent/20 text-primary">{state.id === 'AVAILABLE' ? <Check className="size-4" /> : state.id === 'SOLD_OUT' ? <Clock3 className="size-4" /> : <EyeOff className="size-4" />}</span><p className="mt-3 font-black">{state.label}</p><p className="mt-1 text-xs text-muted-foreground">{state.description}</p></button>)}</div><div><p className="font-black text-primary">Disponibilidad por canal</p><div className="mt-3 grid gap-3 sm:grid-cols-2 lg:grid-cols-4">{Object.entries({ QR: 'Menú QR', TAKEAWAY: 'Retiro en tienda', DINE_IN: 'Salón y mesas', DELIVERY: 'Delivery' }).map(([id, label]) => <label key={id} className="flex items-center justify-between rounded-xl border border-border/60 p-3 text-sm font-bold"><span>{label}</span><input type="checkbox" checked={Boolean(draft.channels[id])} onChange={(event) => updateDraft('channels', { ...draft.channels, [id]: event.target.checked })} /></label>)}</div></div><div className="rounded-2xl border border-border/60 p-4"><div className="flex items-center justify-between"><div><p className="font-black text-primary">Horario de disponibilidad</p><p className="text-xs text-muted-foreground">Define los días y horas en que se puede pedir.</p></div><Button className={accentButton} size="sm" onClick={() => updateDraft('schedule', emptySchedule())}><Clock3 className="size-4" />Restablecer horario</Button></div><div className="mt-3 space-y-2">{draft.schedule.map((row) => <div key={row.day} className="grid items-center gap-2 sm:grid-cols-[110px_70px_1fr_1fr]"><label className="flex items-center gap-2 text-sm font-bold"><input type="checkbox" checked={row.enabled} onChange={(event) => updateDraft('schedule', draft.schedule.map((current) => current.day === row.day ? { ...current, enabled: event.target.checked } : current))} />{dayNames[row.day]}</label><span className="text-xs text-muted-foreground">{row.enabled ? 'Activo' : 'Cerrado'}</span><Input type="time" value={row.from} disabled={!row.enabled} onChange={(event) => updateDraft('schedule', draft.schedule.map((current) => current.day === row.day ? { ...current, from: event.target.value } : current))} /><Input type="time" value={row.to} disabled={!row.enabled} onChange={(event) => updateDraft('schedule', draft.schedule.map((current) => current.day === row.day ? { ...current, to: event.target.value } : current))} /></div>)}</div></div><label className="flex items-center justify-between rounded-xl border border-border/60 p-3 text-sm font-bold"><span>Pausa temporal en todos los canales</span><input type="checkbox" checked={draft.temporaryPause} onChange={(event) => updateDraft('temporaryPause', event.target.checked)} /></label><label className="flex items-center justify-between rounded-xl border border-border/60 p-3 text-sm font-bold"><span>Marcar como recomendado<small className="block font-normal text-muted-foreground">Destaca este platillo en el menú público.</small></span><input type="checkbox" checked={draft.featured} onChange={(event) => updateDraft('featured', event.target.checked)} /></label></div>}
    </div><PreviewCard draft={draft} /></div></div>}
    {view === 'design' && <div className="space-y-5"><div className="flex flex-wrap items-start justify-between gap-3"><div><button type="button" onClick={() => setView('templates')} className="mb-3 flex items-center gap-2 text-xs font-bold text-muted-foreground hover:text-primary"><ArrowLeft className="size-4" />Volver a plantillas</button><p className="text-xs font-black uppercase tracking-widest text-primary">Restaurante · Carta y menú</p><h2 className="mt-1 font-serif text-3xl font-medium italic text-primary">Editor visual de carta</h2><p className="mt-1 text-sm text-muted-foreground">Personaliza la apariencia de tu menú público. Los cambios se reflejan en tiempo real.</p></div><div className="flex gap-2"><Button variant="outline" onClick={() => window.open(publicLink || '#', '_blank')} disabled={!publicLink}><Globe2 className="size-4" />Ver menú público</Button><Button className={primaryButton} onClick={() => void saveSettings()} disabled={!canEdit || saving}><Check className="size-4" />Guardar cambios</Button></div></div><div className="grid gap-2 rounded-2xl border border-border/60 bg-card p-3 sm:grid-cols-3">{([{ id: 'appearance', label: 'Apariencia' }, { id: 'content', label: 'Contenido' }, { id: 'publication', label: 'Publicación' }] as const).map((step, index) => <button key={step.id} type="button" onClick={() => setDesignStep(step.id)} className={`flex items-center gap-3 rounded-xl px-4 py-3 text-left ${designStep === step.id ? 'bg-primary/10 text-primary' : 'text-muted-foreground hover:bg-muted/50'}`}><span className={`flex size-8 items-center justify-center rounded-full text-xs font-black ${designStep === step.id ? 'bg-primary text-primary-foreground' : 'bg-muted text-muted-foreground'}`}>{index + 1}</span><span className="text-sm font-black">{step.label}</span></button>)}</div><div className="grid gap-5 xl:grid-cols-[minmax(0,1fr)_390px]"><div className="space-y-5 rounded-2xl border border-border/60 bg-card p-5 shadow-sm">{designStep === 'appearance' && <><div><p className="font-serif text-xl font-medium italic text-primary">Marca y portada</p><p className="mt-1 text-sm text-muted-foreground">Configura la identidad visual de tu menú.</p></div><div className="grid gap-4 md:grid-cols-2"><div className="rounded-2xl border border-border/60 p-4"><p className="text-sm font-black">Logo del restaurante</p><div className="mt-3 flex h-32 items-center justify-center overflow-hidden rounded-xl bg-muted/40">{logoPreview ? <img src={logoPreview} alt="Logo del restaurante" className="size-full object-contain p-4" /> : <span className="font-serif text-xl font-medium italic text-primary">NovaHub</span>}</div><input ref={logoInputRef} type="file" accept="image/png,image/jpeg,image/webp" className="hidden" onChange={(event) => { void uploadBrandAsset(event.target.files?.[0], 'logo'); event.currentTarget.value = ''; }} />{canConfigureRestaurant && <Button className="mt-3 w-full" variant="outline" onClick={() => logoInputRef.current?.click()} disabled={saving}><ImagePlus className="size-4" />Cambiar imagen</Button>}</div><div className="rounded-2xl border border-border/60 p-4"><p className="text-sm font-black">Imagen de portada</p><div className="mt-3 h-32 overflow-hidden rounded-xl bg-muted/40">{coverPreview ? <img src={coverPreview} alt="Portada del menú" className="size-full object-cover" /> : <div className="flex size-full items-center justify-center text-muted-foreground"><ImagePlus className="size-7" /></div>}</div><input ref={coverInputRef} type="file" accept="image/png,image/jpeg,image/webp" className="hidden" onChange={(event) => { void uploadBrandAsset(event.target.files?.[0], 'cover'); event.currentTarget.value = ''; }} />{canConfigureRestaurant && <Button className="mt-3 w-full" variant="outline" onClick={() => coverInputRef.current?.click()} disabled={saving}><ImagePlus className="size-4" />Cambiar imagen</Button>}</div></div><div className="rounded-2xl border border-border/60 p-4"><p className="font-serif text-xl font-medium italic text-primary">Colores del menú</p>{canConfigureRestaurant && <div className="mt-4 grid gap-4 sm:grid-cols-2"><label className="flex items-center gap-3 rounded-xl border border-border/60 p-3 text-sm font-bold"><input type="color" value={primaryColor} onChange={(event) => setPrimaryColor(event.target.value)} onBlur={(event) => void saveBrandColor('primaryColor', event.target.value)} className="size-10 cursor-pointer rounded-lg border-0 bg-transparent" /><span>Verde bosque<small className="mt-1 block font-mono text-xs text-muted-foreground">{primaryColor}</small></span></label><label className="flex items-center gap-3 rounded-xl border border-border/60 p-3 text-sm font-bold"><input type="color" value={accentColor} onChange={(event) => setAccentColor(event.target.value)} onBlur={(event) => void saveBrandColor('accentColor', event.target.value)} className="size-10 cursor-pointer rounded-lg border-0 bg-transparent" /><span>Verde Nova / acento<small className="mt-1 block font-mono text-xs text-muted-foreground">{accentColor}</small></span></label></div>}</div></>}{designStep === 'content' && <><div><p className="font-serif text-xl font-medium italic text-primary">Información a mostrar</p><p className="mt-1 text-sm text-muted-foreground">Decide qué verá el cliente en la carta pública.</p></div>{[{ label: 'Mostrar descripciones de los platillos', checked: showDescriptions, set: setShowDescriptions }, { label: 'Mostrar precios', checked: showPrices, set: setShowPrices }, { label: 'Mostrar fotos de los platillos', checked: showImages, set: (value: boolean) => { void saveSettings(undefined, value); } }, { label: 'Mostrar alérgenos e información nutricional', checked: showAllergens, set: setShowAllergens }, { label: 'Mostrar pie de página con la marca NovaHub', checked: showFooter, set: setShowFooter }].map((option) => <label key={option.label} className="flex items-center justify-between rounded-xl border border-border/60 p-3 text-sm font-semibold"><span>{option.label}</span><button type="button" role="switch" aria-checked={option.checked} onClick={() => option.set(!option.checked)} className={`relative h-6 w-11 rounded-full transition ${option.checked ? 'bg-accent' : 'bg-muted'}`}><span className={`absolute top-0.5 size-5 rounded-full bg-white shadow transition-all ${option.checked ? 'left-[22px]' : 'left-0.5'}`} /></button></label>)}<div className="rounded-2xl border border-border/60 p-4"><div className="flex items-center gap-2"><Languages className="size-5 text-accent" /><p className="font-black text-primary">Idioma del menú</p></div><div className="mt-3 flex flex-wrap gap-2">{(['ES', 'EN', 'BOTH'] as const).map((value) => <Button key={value} size="sm" variant={language === value ? 'default' : 'outline'} onClick={() => void saveSettings(undefined, undefined, value)} disabled={!canEdit}>{value === 'BOTH' ? 'Español + English' : value === 'ES' ? 'Solo español' : 'Solo inglés'}</Button>)}</div></div></>}{designStep === 'publication' && <><div><p className="font-serif text-xl font-medium italic text-primary">Publicación de tu carta</p><p className="mt-1 text-sm text-muted-foreground">Comparte el enlace y prepara el código QR para tus clientes.</p></div><div className="rounded-2xl border border-border/60 p-4"><p className="text-xs font-black uppercase tracking-widest text-muted-foreground">Enlace público</p><p className="mt-3 break-all rounded-xl bg-muted/40 p-3 text-sm font-semibold">{publicLink || 'Configura un canal público para generar el enlace.'}</p><div className="mt-3 flex flex-wrap gap-2"><Button variant="outline" onClick={() => publicLink && void navigator.clipboard.writeText(publicLink).then(() => toast.success('Enlace copiado.'))} disabled={!publicLink}><Copy className="size-4" />Copiar enlace</Button><Button variant="outline" onClick={() => void openMenuQr()}><QrCode className="size-4" />Gestionar QR</Button></div></div><div className="rounded-2xl border border-accent/30 bg-accent/5 p-4"><p className="font-black text-primary">Plantilla activa</p><p className="mt-1 font-serif text-2xl font-medium italic text-primary">{themes.find((item) => item.id === theme)?.label}</p><Button className="mt-3" variant="outline" onClick={() => setView('templates')}><BookOpen className="size-4" />Cambiar plantilla</Button></div></>}</div><aside className="rounded-2xl border border-accent/30 bg-accent/5 p-5 shadow-sm"><div className="flex items-center gap-2"><Smartphone className="size-5 text-primary" /><div><p className="font-black text-primary">Vista previa en móvil</p><p className="text-xs text-muted-foreground">Así verá tu cliente la carta.</p></div></div><div className="mx-auto mt-5 max-w-[280px] overflow-hidden rounded-[2.25rem] border-[8px] border-slate-800 bg-white shadow-xl"><div className="h-7 bg-slate-900" /><div className="p-3" style={{ backgroundColor: `${accentColor}20` }}><div className="flex items-center justify-between"><span className="text-lg font-black" style={{ color: primaryColor }}>☰</span><span className="font-serif text-base font-medium italic" style={{ color: primaryColor }}>Café del Parque</span><span style={{ color: accentColor }}>♡</span></div>{coverPreview ? <img src={coverPreview} alt="Vista previa de portada" className="mt-3 h-32 w-full rounded-xl object-cover" /> : <div className="mt-3 flex h-32 items-center justify-center rounded-xl bg-gradient-to-br from-[#01422C] to-[#74C044] text-sm font-black text-white">Tu carta pública</div>}<p className="mt-4 font-serif text-xl font-medium italic" style={{ color: primaryColor }}>Cafés</p>{allItems.slice(0, 4).map(({ item }) => <div key={item.id} className="flex items-center justify-between border-b border-border/60 py-3"><div><p className="text-xs font-black">{item.name}</p>{showDescriptions && <p className="mt-1 text-[10px] text-muted-foreground">{item.description || 'Deliciosa opción de la casa'}</p>}{showPrices && <p className="mt-1 text-xs font-black" style={{ color: accentColor }}>{money(item.price, item.currency)}</p>}</div>{showImages && item.imageUrl && <img src={item.imageUrl} alt="" className="size-10 rounded-lg object-cover" />}</div>)}</div>{showFooter && <div className="bg-[#f5ead8] px-3 py-4 text-center text-[10px] font-semibold text-[#01422C]">Powered by NovaHub</div>}</div></aside></div></div>}
    {categoryModalOpen && <div className="fixed inset-0 z-50 flex items-center justify-center bg-foreground/60 p-4" role="dialog" aria-modal="true" aria-labelledby="category-dialog-title"><div className="w-full max-w-md rounded-3xl border border-border/60 bg-card p-6 shadow-2xl"><div className="flex items-start justify-between"><div><p className="text-xs font-black uppercase tracking-widest text-primary">Carta y menú</p><h3 id="category-dialog-title" className="mt-1 font-serif text-2xl font-medium italic text-primary">{categoryForm.id ? 'Editar categoría' : 'Agregar categoría'}</h3></div><button type="button" onClick={resetCategory} aria-label="Cerrar"><X className="size-5" /></button></div><div className="mt-5 space-y-3"><label className="text-sm font-bold">Nombre<Input className="mt-2" value={categoryForm.name} onChange={(event) => setCategoryForm((current) => ({ ...current, name: event.target.value }))} autoFocus /></label><label className="text-sm font-bold">Descripción <span className="font-normal text-muted-foreground">(opcional)</span><textarea className="mt-2 min-h-24 w-full rounded-xl border border-input bg-background px-3 py-2 text-sm" value={categoryForm.description} onChange={(event) => setCategoryForm((current) => ({ ...current, description: event.target.value }))} /></label></div><div className="mt-5 flex justify-end gap-2"><Button variant="outline" onClick={resetCategory}>Cancelar</Button><Button className={accentButton} onClick={() => void saveCategory()} disabled={saving}>{saving ? 'Guardando…' : 'Guardar categoría'}</Button></div></div></div>}
    {showQr && <div className="fixed inset-0 z-50 flex items-center justify-center bg-foreground/60 p-4" role="dialog" aria-modal="true" aria-labelledby="menu-qr-title"><div className="w-full max-w-md rounded-3xl border border-border/60 bg-card p-6 shadow-2xl"><div className="flex items-start justify-between gap-3"><div><p className="text-xs font-black uppercase tracking-widest text-primary">Carta y menú</p><h3 id="menu-qr-title" className="mt-1 font-serif text-2xl font-medium italic text-primary">Código QR del menú</h3></div><button type="button" onClick={() => setShowQr(false)} className="rounded-xl p-2 text-muted-foreground hover:bg-muted" aria-label="Cerrar QR"><X className="size-5" /></button></div><div className="mt-5 flex justify-center rounded-2xl bg-white p-5"><img src={qrPreview} alt="Código QR del menú público" className="size-64 max-w-full" /></div><div className="mt-4 grid grid-cols-2 gap-2"><a href={qrPreview} download="novahub-menu-qr.png" className="inline-flex h-10 items-center justify-center gap-2 rounded-xl bg-primary px-4 text-sm font-bold text-primary-foreground hover:bg-primary/90"><Download className="size-4" />Descargar PNG</a><Button variant="outline" onClick={() => publicLink && void navigator.clipboard.writeText(publicLink).then(() => toast.success('Enlace copiado.'))}><Copy className="size-4" />Copiar enlace</Button></div></div></div>}
  </section>;
}
